<?php
namespace Portal\Models;
use PDO;
final class Conteudo { public function __construct(private PDO $db) {} public function published(int $limit=12): array { $s=$this->db->prepare("SELECT c.*,ca.nome categoria,ca.slug categoria_slug,u.nome autor FROM conteudos c JOIN categorias ca ON ca.id=c.categoria_id JOIN usuarios u ON u.id=c.autor_id WHERE c.status='publicado' AND c.publicado_em<=NOW() ORDER BY c.destaque DESC,c.publicado_em DESC LIMIT :limite"); $s->bindValue('limite',$limit,PDO::PARAM_INT); $s->execute(); return $s->fetchAll(); } public function findPublished(string $slug): ?array { $s=$this->db->prepare("SELECT c.*,ca.nome categoria,u.nome autor FROM conteudos c JOIN categorias ca ON ca.id=c.categoria_id JOIN usuarios u ON u.id=c.autor_id WHERE c.slug=:slug AND c.status='publicado'");$s->execute(['slug'=>$slug]);return $s->fetch() ?: null;} public function all(): array {return $this->db->query('SELECT c.*,ca.nome categoria,u.nome autor FROM conteudos c JOIN categorias ca ON ca.id=c.categoria_id JOIN usuarios u ON u.id=c.autor_id ORDER BY c.criado_em DESC')->fetchAll();} public function save(array $d,int $authorId): void {$s=$this->db->prepare("INSERT INTO conteudos (titulo,slug,resumo,corpo,categoria_id,autor_id,status,destaque,publicado_em) VALUES (:titulo,:slug,:resumo,:corpo,:categoria,:autor,:status,:destaque,CASE WHEN :status='publicado' THEN NOW() ELSE NULL END)");$s->execute(['titulo'=>$d['titulo'],'slug'=>$d['slug'],'resumo'=>$d['resumo'],'corpo'=>$d['corpo'],'categoria'=>$d['categoria_id'],'autor'=>$authorId,'status'=>$d['status'],'destaque'=>isset($d['destaque'])]);} }
